// 高亮显示搜索关键字的组件
const HighlightText = ({ text, searchKeyword }: { text: string; searchKeyword: string }) => {
  if (!searchKeyword || !text) return <span>{text}</span>

  const regex = new RegExp(`(${searchKeyword})`, "gi")
  const parts = text.split(regex)

  return (
    <span>
      {parts.map((part, index) =>
        regex.test(part) ? (
          <mark key={index} className="bg-yellow-200">
            {part}
          </mark>
        ) : (
          part
        ),
      )}
    </span>
  )
}

export function InfoHoverCard({ data }: { data: vps }) {
  const { keyword } = useStore()
  // 判断是否在线 - 根据最后活跃时间
  const isOnline = (() => {
    const lastActive = dayjs(data.last_active)
    const now = dayjs()
    const diffMinutes = now.diff(lastActive, "minute")
    return diffMinutes < 99999 // 5分钟内视为在线
  })()
  const Icon = platforms[data.host.platform?.toLocaleLowerCase() as keyof typeof platforms]

  return (
    <Link to={`/server/${data.id}`}>
      <div className="flex items-center gap-2 line-clamp-1 cursor-pointer pl-2 w-full overflow-hidden hover:bg-accent/50 rounded-md ">
        <span className="relative flex h-2 w-2">
          <span
            className={`absolute inline-flex h-full w-full animate-ping rounded-full ${isOnline ? "bg-primary" : "bg-red-500"} opacity-75`}
          ></span>
          <span className={`relative inline-flex h-2 w-2 rounded-full ${isOnline ? "bg-primary" : "bg-red-500"}`}></span>
        </span>
        <div className="flex items-center text-foreground font-medium truncate text-xs underline-hover gap-0.5">
          {Icon && Icon}
          <ServerFlag country_code={data.country_code!} className="" />
          <div>
            <HighlightText text={data.name} searchKeyword={keyword} />
          </div>
        </div>
      </div>
    </Link>
  )
}
